CREATE TABLE IF NOT EXISTS schema_migrations (version integer PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS intersections (id text PRIMARY KEY, name text NOT NULL, x double precision NOT NULL, z double precision NOT NULL, configuration jsonb NOT NULL DEFAULT '{}');
CREATE TABLE IF NOT EXISTS lanes (id text PRIMARY KEY, intersection_id text NOT NULL REFERENCES intersections(id), direction text NOT NULL, capacity integer NOT NULL CHECK (capacity > 0));
CREATE TABLE IF NOT EXISTS events (id text PRIMARY KEY, type text NOT NULL, timestamp timestamptz NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS events_timestamp_idx ON events(timestamp DESC);
CREATE INDEX IF NOT EXISTS events_correlation_idx ON events(correlation_id);
CREATE TABLE IF NOT EXISTS optimization_decisions (id text PRIMARY KEY, intersection_id text NOT NULL, created_at timestamptz NOT NULL, correlation_id text NOT NULL, payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS decisions_created_idx ON optimization_decisions(created_at DESC);
CREATE TABLE IF NOT EXISTS signal_transitions (id text PRIMARY KEY REFERENCES events(id), intersection_id text NOT NULL, created_at timestamptz NOT NULL, payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS signal_states (intersection_id text PRIMARY KEY REFERENCES intersections(id), updated_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS traffic_snapshots (id bigserial PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE INDEX IF NOT EXISTS snapshots_time_idx ON traffic_snapshots(created_at DESC);
CREATE TABLE IF NOT EXISTS incidents (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS emergency_vehicles (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS emergency_corridors (id text PRIMARY KEY, created_at timestamptz NOT NULL DEFAULT now(), payload jsonb NOT NULL);
CREATE TABLE IF NOT EXISTS emergency_reservations (corridor_id text NOT NULL REFERENCES emergency_corridors(id), intersection_id text NOT NULL, payload jsonb NOT NULL, PRIMARY KEY(corridor_id, intersection_id));
CREATE TABLE IF NOT EXISTS idempotency_keys (key text PRIMARY KEY, fingerprint text NOT NULL, status integer NOT NULL, response jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS event_outbox (id text PRIMARY KEY REFERENCES events(id), payload jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), published_at timestamptz);
CREATE INDEX IF NOT EXISTS outbox_pending_idx ON event_outbox(created_at) WHERE published_at IS NULL;
INSERT INTO schema_migrations(version) VALUES(1) ON CONFLICT DO NOTHING;
